== 1 and 1 <= x.numel() <= 131072,\n43:             \"x must have shape [N] with N in [1,131072]\")\n44:     require(x.dtype == torch.float16, \"FP16 input required\")\n45:     require(bool(torch.isfinite(x).all().item()), \"all input values must be finite\")\n46:     return {\"valid\": True, \"size\": x.numel()}\n47: \n48: \n49: def run(x):\n50:     \"\"\"Return sigmoid values in a fresh FP16 tensor.\"\"\"\n51:     validate_inputs(x)\n52:     with torch.cuda.device(x.device):\n53:         output = torch.empty_like(x)\n54:         _sigmoid[(triton.cdiv(x.numel(), 256),)](\n55:             x, output, N=x.numel(), BLOCK=256, num_warps=4,\n56:             enable_fp_fusion=False)\n57:     return output\n58: \n59: \n60: def reference(x):\n61:     \"\"\"CPU FP64 sigmoid, then direct binary16 round-to-nearest-even packing.\"\"\"\n62:     import struct\n63:     validate_inputs(x, require_cuda=False)\n64:     values = x.detach().to(device=\"cpu\", dtype=torch.float64)\n65:     payload = bytearray().join(struct.pack(\"<e\", value)\n66:                                for value in torch.sigmoid(values).tolist())\n67:     result = torch.frombuffer(payload, dtype=torch.float16).clone()\n68:     return result.to(x.device)\n69: \n70: \n71: def make_inputs(device=\"cuda\", size=4093, seed=0):\n72:     \"\"\"Convenience inputs; all finite FP16 values belong to the legal domain.\"\"\"\n73:     generator = torch.Generator(device=\"cpu\").manual_seed(seed)\n74:     x = (3.0 * torch.randn((size,), generator=generator)).to(torch.float16)\n75:     return (x.to(device),)",
